/**
 * Writes the effective SQL schema to `docs/schema.sql` so that database
 * administrators can review or apply the schema by hand.
 *
 *   npm run schema:dump
 */
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { MIGRATIONS } from '../db/migrate.js';

async function main(): Promise<void> {
  const target = resolve(process.cwd(), 'docs/schema.sql');
  const header = [
    '-- shopifytoodoo - central order management schema',
    '-- Generated by `npm run schema:dump`; do not edit by hand.',
    '',
  ].join('\n');
  const body = MIGRATIONS.map(
    (migration) => `-- migration ${migration.id}\n${migration.sql.trim()}\n`,
  ).join('\n');
  await mkdir(dirname(target), { recursive: true });
  await writeFile(target, `${header}${body}`, 'utf8');
  console.log(`Schema written to ${target}`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
